L["Macro: %s"] = "Macro : %s"
L["Does the same as this control. Make a macro with that line, put it on an action bar, and bind that slot to a controller button in the game's Key Bindings."] = "Fait la même chose que cette commande. Créez une macro avec cette ligne, placez-la sur une barre d'action et assignez cet emplacement à un bouton de la manette dans les raccourcis du jeu."
L["As a macro it's one step a press."] = "En macro, c'est un pas par appui."
L["/agps pad select|yes|remove|back|recenter | menu | zoom in|out | pan up|down|left|right  (the controller's controls, for macros)"] = "/agps pad select|yes|remove|back|recenter | menu | zoom in|out | pan up|down|left|right  (les commandes de la manette, pour les macros)"
